[{"order":1,"type":"heading","text":"Enterprise Logging, Sentry Integration, and APM in Django"},{"order":2,"type":"paragraph","text":"Robust observability is critical for maintaining production Django applications. This tutorial covers setting up advanced Python logging, integrating Sentry for real-time error tracking, and configuring Application Performance Monitoring (APM) tools like Elastic APM or Datadog."},{"order":3,"type":"subheading","text":"1. Configuring Django Logging"},{"order":4,"type":"paragraph","text":"Django relies on Python's built-in logging module. For production environments, it is best practice to structure logs in JSON format for easy ingestion by log aggregators."},{"order":5,"type":"code","text":"LOGGING = {
    'version': 1,
    'disable_existing_loggers': False,
    'formatters': {
        'verbose': {
            'format': '{levelname} {asctime} {module} {process:d} {thread:d} {message}',
            'style': '{',
        },
    },
    'handlers': {
        'console': {
            'level': 'INFO',
            'class': 'logging.StreamHandler',
            'formatter': 'verbose',
        },
    },
    'root': {
        'handlers': ['console'],
        'level': 'INFO',
    },
    'loggers': {
        'django': {
            'handlers': ['console'],
            'level': 'INFO',
            'propagate': False,
        },
    },
}"},{"order":6,"type":"subheading","text":"2. Integrating Sentry for Error Tracking"},{"order":7,"type":"paragraph","text":"Sentry captures unhandled exceptions and provides deep stack traces along with request context. First, install the official SDK using pip install sentry-sdk."},{"order":8,"type":"code","text":"import sentry_sdk
from sentry_sdk.integrations.django import DjangoIntegration

sentry_sdk.init(
    dsn="YOUR_SENTRY_DSN_HERE",
    integrations=[DjangoIntegration()],
    traces_sample_rate=1.0,
    send_default_pii=True
)"},{"order":9,"type":"subheading","text":"3. Setting Up APM Tools"},{"order":10,"type":"paragraph","text":"APM tools monitor transaction performance, database query latencies, and external API calls. Below is an example of configuring Elastic APM in your settings.py file."},{"order":11,"type":"code","text":"INSTALLED_APPS = [
    ...
    'elasticapm.contrib.django',
]

ELASTIC_APM = {
    'SERVICE_NAME': 'my-django-app',
    'SECRET_TOKEN': 'YOUR_ELASTIC_TOKEN',
    'SERVER_URL': 'https://apm-server-url.elastic.co:443',
    'ENVIRONMENT': 'production',
}"},{"order":12,"type":"subheading","text":"Best Practices"},{"order":13,"type":"bullet_point","text":"Never hardcode DSNs or secret tokens; use environment variables via libraries like django-environ."},{"order":14,"type":"bullet_point","text":"Adjust your APM traces_sample_rate in high-traffic production environments to manage ingestion costs."},{"order":15,"type":"bullet_point","text":"Ensure send_default_pii is handled carefully to comply with data privacy regulations like GDPR."}]
